   paths.Points=views.Where(v=>v.region>=0).OrderBy(v=>v.region).SelectMany(v=>v.groups.Where(p=>p.gameObject.activeSelf).Select(p=>(RectTransform)p.transform)).ToArray();paths.SetVerticesDirty();
